"use client"

import * as React from "react"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"
import { SoftButton } from "@/components/belgrade/ui"

/**
 * A button that opens a video in a modal `<dialog>`. The native dialog traps
 * focus, closes on Escape and returns focus to the button. The video is only
 * fetched once the dialog opens.
 */
export function VideoDialog({
  src,
  poster,
  title = "Video",
  className,
  children,
}: {
  src: string
  poster?: string
  title?: string
  className?: string
  children: React.ReactNode
}) {
  const dialogRef = React.useRef<HTMLDialogElement>(null)
  const videoRef = React.useRef<HTMLVideoElement>(null)
  const [failed, setFailed] = React.useState(false)

  function open() {
    dialogRef.current?.showModal()
    document.documentElement.style.overflow = "hidden"
    videoRef.current?.play().catch(() => {})
  }

  function handleClose() {
    videoRef.current?.pause()
    document.documentElement.style.overflow = ""
  }

  return (
    <>
      <SoftButton onClick={open} className={className}>
        {children}
      </SoftButton>

      <dialog
        ref={dialogRef}
        aria-label={title}
        onClose={handleClose}
        // Clicks on the backdrop land on the dialog itself.
        onClick={(event) => {
          if (event.target === event.currentTarget) event.currentTarget.close()
        }}
        className="m-auto w-[min(960px,calc(100vw-2rem))] max-w-none overflow-visible bg-transparent p-0 opacity-0 transition-[opacity,scale,display,overlay] transition-discrete duration-300 ease-out scale-95 open:scale-100 open:opacity-100 starting:open:scale-95 starting:open:opacity-0 backdrop:bg-black/0 backdrop:transition-[background-color,display,overlay] backdrop:transition-discrete backdrop:duration-300 open:backdrop:bg-black/75 starting:open:backdrop:bg-black/0"
      >
        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-black shadow-[0_40px_120px_-30px_rgb(0_0_0/0.9)]">
          <video
            ref={videoRef}
            src={src}
            poster={poster}
            controls
            playsInline
            preload="none"
            onError={() => setFailed(true)}
            className="aspect-video w-full bg-black"
          />
          {failed && (
            <p className="absolute inset-0 grid place-items-center text-sm text-white/60">
              Video unavailable
            </p>
          )}
          <button
            type="button"
            aria-label="Close video"
            onClick={() => dialogRef.current?.close()}
            className={cn(
              "absolute top-3 right-3 grid size-9 place-items-center rounded-full border border-white/15 bg-black/50 text-white backdrop-blur-md transition-colors hover:bg-black/75",
              "outline-none focus-visible:ring-3 focus-visible:ring-white/40"
            )}
          >
            <X className="size-4" />
          </button>
        </div>
      </dialog>
    </>
  )
}

"use client"

import * as React from "react"
import { flushSync } from "react-dom"
import { Moon, Sun } from "lucide-react"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"
import { useIntro } from "@/components/belgrade/motion"

type Theme = "light" | "dark"

// Same storage key and class strategy as next-themes, so both can coexist.
const STORAGE_KEY = "theme"

const themeScript = `(function(){var d=true;try{var s=localStorage.getItem("${STORAGE_KEY}");d=s==="system"?matchMedia("(prefers-color-scheme: dark)").matches:s!=="light"}catch(_){}var e=document.documentElement;e.classList.toggle("dark",d);e.style.colorScheme=d?"dark":"light"})()`

/**
 * Applies the saved theme before first paint. Dark is the default until the
 * visitor picks light.
 * Renders as an inert `text/plain` script on the client to avoid React's
 * script-tag warning; the server-rendered copy is the one that executes.
 */
export function ThemeScript() {
  return (
    <script
      type={typeof window === "undefined" ? "text/javascript" : "text/plain"}
      suppressHydrationWarning
      dangerouslySetInnerHTML={{ __html: themeScript }}
    />
  )
}

function subscribe(callback: () => void) {
  const observer = new MutationObserver(callback)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  })
  return () => observer.disconnect()
}

const getSnapshot = (): Theme =>
  document.documentElement.classList.contains("dark") ? "dark" : "light"

const getServerSnapshot = (): Theme | null => null

function applyTheme(theme: Theme) {
  const root = document.documentElement
  root.classList.toggle("dark", theme === "dark")
  root.style.colorScheme = theme
  try {
    localStorage.setItem(STORAGE_KEY, theme)
  } catch {}
}

export function useTheme() {
  const theme = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerSnapshot
  )

  const setTheme = React.useCallback(
    (next: Theme, origin?: { x: number; y: number }) => {
      const reduced = window.matchMedia(
        "(prefers-reduced-motion: reduce)"
      ).matches

      if (!document.startViewTransition || reduced || !origin) {
        applyTheme(next)
        return
      }

      const { x, y } = origin
      const radius = Math.hypot(
        Math.max(x, window.innerWidth - x),
        Math.max(y, window.innerHeight - y)
      )

      const transition = document.startViewTransition(() => {
        flushSync(() => applyTheme(next))
      })

      transition.ready.then(() => {
        document.documentElement.animate(
          {
            clipPath: [
              `circle(0px at ${x}px ${y}px)`,
              `circle(${radius}px at ${x}px ${y}px)`,
            ],
          },
          {
            duration: 650,
            easing: "cubic-bezier(0.22, 1, 0.36, 1)",
            pseudoElement: "::view-transition-new(root)",
          }
        )
      })
    },
    []
  )

  return { theme, setTheme }
}

const options = [
  { value: "dark", label: "Dark theme", icon: Moon },
  { value: "light", label: "Light theme", icon: Sun },
] as const

export function ThemeToggle({ className }: { className?: string }) {
  const { theme, setTheme } = useTheme()
  const intro = useIntro()

  return (
    <motion.div
      role="radiogroup"
      aria-label="Color theme"
      initial={intro ? { opacity: 0, y: 16, scale: 0.9 } : false}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ delay: 1.2, type: "spring", stiffness: 260, damping: 22 }}
      className={cn(
        "fixed right-4 bottom-4 z-50 flex items-center gap-0.5 rounded-xl border border-border bg-surface p-1 shadow-[0_8px_24px_-8px_rgb(0_0_0/0.25)] backdrop-blur-xl",
        className
      )}
    >
      {options.map(({ value, label, icon: Icon }) => {
        const active = theme === value
        return (
          <button
            key={value}
            type="button"
            role="radio"
            aria-checked={active}
            aria-label={label}
            onClick={(event) =>
              setTheme(value, { x: event.clientX, y: event.clientY })
            }
            className={cn(
              "relative grid size-7 place-items-center rounded-lg transition-colors duration-300",
              active
                ? "text-background"
                : "text-muted-foreground hover:text-foreground"
            )}
          >
            {active && (
              <motion.span
                layoutId="belgrade-theme-thumb"
                className="absolute inset-0 rounded-lg bg-foreground"
                transition={{ type: "spring", stiffness: 420, damping: 32 }}
              />
            )}
            <motion.span
              className="relative"
              animate={{ rotate: active ? 0 : -45, scale: active ? 1 : 0.85 }}
              transition={{ type: "spring", stiffness: 300, damping: 18 }}
            >
              <Icon className="size-3.5" strokeWidth={2.25} />
            </motion.span>
          </button>
        )
      })}
    </motion.div>
  )
}

import * as React from "react"
import Link from "next/link"

import { cn } from "@/lib/utils"
import { Reveal } from "@/components/belgrade/motion"

const shine =
  "relative overflow-hidden before:pointer-events-none before:absolute before:inset-y-0 before:-left-full before:w-full before:bg-linear-to-r before:from-transparent before:via-white/35 before:to-transparent before:transition-transform before:duration-700 before:ease-out hover:before:translate-x-[200%]"

const buttonBase =
  "inline-flex h-9 shrink-0 items-center justify-center gap-1.5 rounded-lg px-3.5 text-[15px] whitespace-nowrap outline-none transition-[filter,background-color,box-shadow,translate] focus-visible:ring-3 focus-visible:ring-ring/50 active:translate-y-px disabled:pointer-events-none disabled:opacity-60 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"

const buttonVariants = {
  brand:
    "border border-brand-edge bg-linear-to-b from-brand-from to-brand-to text-white shadow-[inset_0_1px_0_rgb(255_255_255/0.2),0_10px_24px_-10px_rgb(74_119_166/0.9)] hover:brightness-110",
  soft: "border border-border bg-card text-foreground shadow-[0_4px_14px_-6px_rgb(0_0_0/0.18)] before:via-foreground/5 hover:bg-muted/60",
}

type ButtonProps = React.ComponentProps<"button"> & { href?: never }
type LinkProps = Omit<React.ComponentProps<typeof Link>, "href"> & {
  href: string
}

function createButton(variant: keyof typeof buttonVariants) {
  return function BelgradeButton({ className, ...props }: ButtonProps | LinkProps) {
    const classes = cn(shine, buttonBase, buttonVariants[variant], className)
    if (typeof props.href === "string") {
      return <Link {...(props as LinkProps)} className={classes} />
    }
    return <button type="button" {...(props as ButtonProps)} className={classes} />
  }
}

/** Gradient call-to-action. Pass `href` to render a link. */
export const BrandButton = createButton("brand")

/** Neutral secondary action. Pass `href` to render a link. */
export const SoftButton = createButton("soft")

export function Pill({
  className,
  size = "sm",
  ...props
}: React.ComponentProps<"span"> & { size?: "sm" | "lg" }) {
  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full border border-black/5 bg-card text-foreground shadow-[0_6px_16px_-8px_rgb(0_0_0/0.3)] dark:border-white/10",
        size === "sm" ? "px-3 py-1 text-xs" : "px-4 py-2 text-[15px]",
        className
      )}
      {...props}
    />
  )
}

export function Container({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("mx-auto w-full max-w-[1304px] px-4 sm:px-6", className)}
      {...props}
    />
  )
}

export function Divider({ className }: { className?: string }) {
  return (
    <Container>
      <div
        className={cn(
          "h-px w-full bg-linear-to-r from-transparent via-border to-transparent",
          className
        )}
      />
    </Container>
  )
}

export function SectionHeading({
  badge,
  title,
  accent,
  inline = false,
  description,
  className,
  as: Heading = "h2",
}: {
  badge?: string
  title: React.ReactNode
  accent?: React.ReactNode
  inline?: boolean
  description?: React.ReactNode
  className?: string
  as?: "h1" | "h2"
}) {
  return (
    <Reveal
      className={cn(
        "mx-auto flex max-w-2xl flex-col items-center text-center",
        className
      )}
    >
      {badge && <Pill className="mb-4">{badge}</Pill>}
      <Heading className="text-[clamp(1.6rem,3vw,2.1rem)] leading-[1.22] font-normal tracking-[-0.025em] text-balance">
        {title}
        {accent && (
          <>
            {inline ? " " : <br />}
            <span className="text-brand-soft">{accent}</span>
          </>
        )}
      </Heading>
      {description && (
        <p className="mt-4 max-w-[480px] text-[15px] leading-relaxed font-light text-muted-foreground">
          {description}
        </p>
      )}
    </Reveal>
  )
}

